#include <iostream>
#include <algorithm>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

cpp_int combination(long long n, long long r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);

    cpp_int result = 1;
    for (long long i = 1; i <= r; ++i)
        result = result * (n - r + i) / i;

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, a, o;
    cin >> n >> a >> o;

    cpp_int ans = 0;

    for (long long i = 4; i <= n; ++i) {
        long long j = o - i;
        if (j >= 1 && j <= a)
            ans += combination(n, i) * combination(a, j);
    }

    cout << ans;
    return 0;
}

