#include <iostream>
#include <algorithm>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

cpp_int binomial(long long n, long long k) {
    if (k < 0 || k > n) return 0;
    k = min(k, n - k);

    cpp_int result = 1;
    for (long long i = 1; i <= k; ++i) {
        result *= n - k + i;
        result /= i;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, a, o;
    cin >> n >> a >> o;

    long long first = max(4LL, o - a);
    long long last = min(n, o - 1);

    if (first > last) {
        cout << 0;
        return 0;
    }

    long long j = o - first;
    cpp_int term = binomial(n, first) * binomial(a, j);
    cpp_int answer = term;

    for (long long i = first; i < last; ++i) {
        cpp_int numerator = cpp_int(n - i) * j;
        cpp_int denominator = cpp_int(i + 1) * (a - j + 1);
        term = term * numerator / denominator;
        answer += term;
        --j;
    }

    cout << answer;
    return 0;
}

