long long combination(long long n, long long r) {
    if (r < 0 || r > n) return 0;
    r = min(r, n - r);

    long long result = 1;
    for (long long i = 1; i <= r; ++i) {
        long long numerator = n - r + i;
        long long denominator = i;

        long long g = gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;

        g = gcd(result, denominator);
        result /= g;
        denominator /= g;

        result *= numerator;
    }
    return result;
}

